// Start the parsing.
rv = indexer->GoIndex(this, progressFn, completionFn);
if (NS_FAILED(rv)) {
  nsAutoCString prettyPath;
  GetPrettyPath(prettyPath);
  nsPrintfCString msg("Unable to build summary file for %s (error 0x%08X).",
                      prettyPath.get(), static_cast<uint32_t>(rv));
  NS_WARNING(msg.get());
  msg.Append("\nRepairing the folder may fix this issue."_ns);
  MsgLogToConsole4(NS_ConvertUTF8toUTF16(msg), nsDependentCString(__FILE__),
                   __LINE__, nsIScriptError::errorFlag);
  if (listener) {
    // Avoid synchronous re-entrancy: notify the listener via the event loop
    // to ensure the initiating caller has returned and cleared the stack.
    NS_DispatchToCurrentThread(
        NS_NewRunnableFunction("nsMsgLocalMailFolder::OnStopRunningUrl",
                               [listener = RefPtr{listener}, rv]() {
                                 listener->OnStopRunningUrl(nullptr, rv);
                               }));
  }
  return rv;
}

m_parsingFolder = true;
mReparseListener = listener;

nsAutoString msg;
rv = bundle->FormatStringFromName("buildingSummary",
                                  {NS_ConvertUTF8toUTF16(folderName)}, msg);
if (NS_SUCCEEDED(rv)) {
  nsCOMPtr<nsIFeedbackService> feedback =
      mozilla::components::Feedback::Service();
  if (feedback) {
    feedback->ReportStatus(NS_ConvertUTF16toUTF8(msg), "start-meteors"_ns);
  }
}

return NS_OK;
